head.script:
(function(window, document){
  'use strict';
  var KEY = 'brAgeApprovedAtV1';
  var TTL_MS = 2592000000;
  var HASH = '#br-age-pass';
  var root = document.documentElement;

  function report(message, error){
    if(window.console && window.console.warn){ window.console.warn(message, error || ''); }
  }
  function addClass(name){
    if(root && (' ' + String(root.className || '') + ' ').indexOf(' ' + name + ' ') === -1){
      root.className = String(root.className || '') + ' ' + name;
    }
  }
  function removeStoredValue(storage){
    try{ if(storage){ storage.removeItem(KEY); } }catch(error){ report('Unable to clear expired age approval.', error); }
  }
  function validApprovalTime(value){
    var now = new Date().getTime();
    return value > 0 && value <= now && (now - value) <= TTL_MS;
  }
  function storageAccepted(){
    var storage;
    var raw;
    var value;
    try{ storage = window.localStorage || null; }
    catch(error){ report('Age approval storage is unavailable; falling back to URL fragment.', error); return false; }
    if(!storage){ return false; }
    try{ raw = storage.getItem(KEY); }
    catch(error){ report('Unable to read age approval storage; falling back to URL fragment.', error); return false; }
    value = parseInt(raw || '0', 10) || 0;
    if(validApprovalTime(value)){ return true; }
    if(raw){ removeStoredValue(storage); }
    return false;
  }
  function persistHashApproval(){
    var storage;
    if(String(window.location.hash || '').toLowerCase() !== HASH){ return; }
    try{ storage = window.localStorage || null; }
    catch(error){ report('Age approval storage is unavailable; fragment approval cannot be persisted.', error); return; }
    try{ if(storage){ storage.setItem(KEY, String(new Date().getTime())); } }
    catch(error){ report('Unable to persist fragment age approval.', error); }
  }

  if(storageAccepted() || String(window.location.hash || '').toLowerCase() === HASH){
    persistHashApproval();
    addClass('br-age-accepted');
  }
})(window, document);

