background:-webkit-linear-gradient($startSide,$(sidebar.backgroundColorTop) 0,$(sidebar.backgroundColorTop) 20%,$(sidebar.backgroundColorTop.transparent) 100%);
background:linear-gradient(to $startSide,$(sidebar.backgroundColorTop) 0,$(sidebar.backgroundColorTop) 20%,$(sidebar.backgroundColorTop.transparent) 100%);
color:$(profile.text.color);
height:24px
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
.profile-snippet .snippet-fade{
background:-webkit-linear-gradient($startSide,$(sidebar.backgroundColorTopHD) 0,$(sidebar.backgroundColorTopHD) 20%,$(sidebar.backgroundColorTopHD.transparent) 100%);
background:linear-gradient(to $startSide,$(sidebar.backgroundColorTopHD) 0,$(sidebar.backgroundColorTopHD) 20%,$(sidebar.backgroundColorTopHD.transparent) 100%)
}
}
@media screen and (max-width:800px){
.blog-name{
margin-top:0
}
body.item-view .blog-name{
margin:0 48px
}
.centered-bottom{
padding:8px
}
body.item-view .centered-bottom{
padding:0
}
.page_body .centered{
padding:10px 0
}
body.item-view #header,body.item-view .widget.Header{
margin-right:0
}
body.collapsed-header .centered-top-container .blog-name{
display:block
}
body.collapsed-header .centered-top-container .widget.Header h1{
text-align:center
}
.widget.Header header{
padding:0
}
.widget.Header h1{
font-size:$(blog.title.font.size * 24 / 45);
line-height:$(blog.title.font.size * 24 / 45);
margin-bottom:13px
}
body.item-view .widget.Header h1{
text-align:center
}
body.item-view .widget.Header p{
text-align:center
}
.blog-name .widget.PageList{
padding:0
}
body.item-view .centered-top{
margin-bottom:5px
}
.search-action,.search-input{
margin-bottom:-8px
}
.search form{
margin-bottom:8px
}
body.item-view .subscribe-section-container{
margin:5px 0 0 0;
width:100%
}
#page_body.section div.widget.FeaturedPost,div.widget.PopularPosts{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container{
padding:16px
}
div.widget.Blog .blog-posts .post-outer-container .post-outer{
padding:0
}
.post:first-child{
margin:0
}
.post-body .snippet-thumbnail{
margin:0 3vw 3vw 0
}
.post-body .snippet-thumbnail img{
height:20vw;
width:20vw;
max-height:128px;
max-width:128px
}
div.widget.PopularPosts div.item-thumbnail{
margin:0 3vw 3vw 0
}
div.widget.PopularPosts div.item-thumbnail img{
height:20vw;
width:20vw;
max-height:88px;
max-width:88px
}
.post-title{
line-height:1
}
.post-title,.post-title a{
font-size:20px
}
#page_body.section div.widget.FeaturedPost h3 a{
font-size:22px
}
.mobile-ad .inline-ad{
display:block
}
.page_body.has-vertical-ads .vertical-ad-container,.page_body.has-vertical-ads .vertical-ad-container ins{
display:none
}
.page_body.has-vertical-ads .centered .centered-bottom,.page_body.has-vertical-ads .centered .centered-top{
display:block;
width:auto
}
div.post-filter-message div{
padding:8px 16px
}
}
@media screen and (min-width:$(sidebar.width + content.width + content.margin * 2)){
body{
position:relative
}
body.item-view .blog-name{
margin-left:48px
}
.page_body{
margin-left:$(sidebar.width)
}
.search{
margin-left:0
}
.search.focused{
width:100%
}
.sticky{
padding-left:$(sidebar.width)
}
.hamburger-menu{
display:none
}
body.collapsed-header .page_body .centered-top-container{
padding-left:$(sidebar.width);
padding-right:0;
width:100%
}
body.collapsed-header .centered-top-container .search.focused{
width:100%
}
body.collapsed-header .centered-top-container .blog-name{
margin-left:0
}
body.collapsed-header.item-view .centered-top-container .search.focused{
width:calc(100% - 50px)
}
body.collapsed-header.item-view .centered-top-container .blog-name{
margin-left:40px
}
}


/* ================================================================
   BuzzReelC video interface — runtime-safe Blogger skin overrides
   Kept inside b:skin so Blogger serves it in desktop and mobile modes.
   ================================================================ */
html,body{background:#070707!important;color:#f6f6f6!important}
body{margin:0!important;min-height:100vh!important;overflow-x:hidden!important;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;-webkit-font-smoothing:antialiased!important}
*{box-sizing:border-box}
#navbar-iframe,.bg-photo-container,.bg-photo-overlay,.sidebar-container,.dim-overlay,.hamburger-menu,.search,nav .PageList,.subscribe-section-container,#ads,.widget.AdSense,.inline-ad,.adsbygoogle,.widget.FeaturedPost,.widget.PopularPosts,.post-filter-message,.post-header,.post-footer,#comments,.comments,.Attribution,.footer,.BlogArchive,.Label,.Profile,.feed-links,.post-feeds,.blog-feeds,.quickedit,.item-control,.centered-top-placeholder{display:none!important}
.page,.page_body,.centered{width:100%!important;max-width:none!important;min-height:100%!important;margin:0!important;padding:0!important;background:#070707!important}
.centered-top-container,.centered-top-container.sticky{position:fixed!important;left:0!important;right:0!important;top:0!important;z-index:500!important;width:100%!important;height:64px!important;margin:0!important;padding:0!important;transform:none!important;opacity:1!important;background:rgba(7,7,7,.92)!important;border-bottom:1px solid rgba(255,255,255,.10)!important;box-shadow:none!important;-webkit-backdrop-filter:blur(18px)!important;backdrop-filter:blur(18px)!important}
.centered-top{position:relative!important;width:100%!important;max-width:1080px!important;height:64px!important;min-height:64px!important;margin:0 auto!important;padding:0 62px!important;display:flex!important;align-items:center!important;justify-content:center!important}
.clearboth{display:none!important}
.blog-name,body.item-view .blog-name,body.collapsed-header .centered-top-container .blog-name{position:static!important;display:flex!important;align-items:center!important;justify-content:center!important;width:auto!important;min-width:0!important;margin:0!important;padding:0!important;opacity:1!important}
#header,.widget.Header,.header-widget{width:auto!important;margin:0!important;padding:0!important;background:none!important}
.Header h1,.item-view .Header h1,.sticky .Header h1{position:relative!important;display:flex!important;align-items:center!important;justify-content:center!important;gap:10px!important;width:auto!important;margin:0!important;color:#fff!important;font:800 19px/1.1 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;letter-spacing:-.035em!important;text-align:center!important;white-space:nowrap!important}
.Header h1:before{content:"";width:31px;height:25px;flex:0 0 auto;border-radius:8px;background:#fff;box-shadow:0 8px 26px rgba(255,255,255,.08)}
.Header h1:after{content:"";position:absolute;left:12px;top:50%;width:0;height:0;margin-top:-5px;border-top:5px solid transparent;border-bottom:5px solid transparent;border-left:8px solid #080808;pointer-events:none}
.Header h1 a,.Header h1 a:hover,.Header h1 a:visited{max-width:62vw!important;overflow:hidden!important;color:#fff!important;text-overflow:ellipsis!important;text-decoration:none!important}
.Header p{display:none!important}
.return_link{position:absolute!important;left:11px!important;top:50%!important;z-index:4!important;width:42px!important;height:42px!important;margin-top:-21px!important;display:grid!important;place-items:center!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:50%!important;background:rgba(255,255,255,.055)!important;color:#eee!important;box-shadow:0 8px 24px rgba(0,0,0,.30)!important;-webkit-tap-highlight-color:transparent!important;transition:transform .08s cubic-bezier(.22,1,.36,1),background .08s ease!important}
.return_link:active{transform:scale(.91)!important}.return_link:hover{background:rgba(255,255,255,.11)!important}
.return_link .back-button{width:22px!important;height:22px!important;margin:0!important;padding:0!important;color:#eee!important;fill:#eee!important;background:none!important}.return_link .splash-wrapper{display:none!important}
main.centered-bottom,body.item-view main.centered-bottom{width:100%!important;max-width:1080px!important;min-height:100vh!important;margin:0 auto!important;padding:82px 13px 42px!important;background:#070707!important}
#page_body,.widget.Blog,.widget.Blog .widget-content{width:100%!important;margin:0!important;padding:0!important;background:transparent!important;border:0!important;box-shadow:none!important}.main-heading,.widget.Blog>.title{display:none!important}
.Blog .blog-posts{display:grid!important;grid-template-columns:minmax(0,1fr)!important;gap:25px!important;counter-reset:br-video!important;margin:0!important;padding:0!important}
body.item-view .Blog .blog-posts{display:block!important}
.Blog .blog-posts .post-outer-container,div.widget.Blog .blog-posts .post-outer-container{width:auto!important;min-width:0!important;min-height:0!important;margin:0!important;padding:0!important;border:0!important;background:transparent!important;box-shadow:none!important;counter-increment:br-video!important}
.Blog .blog-posts .post-outer-container .post-outer,div.widget.Blog .blog-posts .post-outer-container .post-outer{position:static!important;margin:0!important;padding:0!important;border:0!important;background:transparent!important;box-shadow:none!important}
.br-video-card,.br-player-post{min-width:0!important;color:#f6f6f6!important}.br-thumb-link{display:block!important;color:inherit!important;text-decoration:none!important;-webkit-tap-highlight-color:transparent!important}
.br-thumb,.br-player-shell{position:relative!important;width:100%!important;height:0!important;padding-top:56.25%!important;overflow:hidden!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:15px!important;background:linear-gradient(135deg,#242424,#0e0e0e 66%,#181818)!important;box-shadow:0 18px 55px rgba(0,0,0,.38)!important;isolation:isolate!important}
.br-thumb{transition:transform .08s cubic-bezier(.22,1,.36,1)!important}.br-thumb-link:active .br-thumb{transform:scale(.986)!important}
.br-media,.br-media>*{position:absolute!important;left:0!important;right:0!important;top:0!important;bottom:0!important;width:100%!important;height:100%!important;margin:0!important;padding:0!important}
.br-media picture,.br-media a{display:block!important}
.br-media img{position:absolute!important;left:0!important;top:0!important;width:100%!important;height:100%!important;max-width:none!important;margin:0!important;padding:0!important;object-fit:cover!important;object-position:center!important;display:block!important;border:0!important}
.br-media-placeholder{background:radial-gradient(circle at 65% 20%,#292929,#111 55%,#0a0a0a)!important}
.br-thumb-shade,.br-player-shade{position:absolute!important;left:0!important;right:0!important;top:0!important;bottom:0!important;z-index:1!important;pointer-events:none!important;background:linear-gradient(to bottom,rgba(0,0,0,.04),transparent 48%,rgba(0,0,0,.64))!important}
.br-play-circle,.br-center-play{position:absolute!important;left:50%!important;top:50%!important;z-index:3!important;display:grid!important;place-items:center!important;border:1px solid rgba(255,255,255,.30)!important;border-radius:50%!important;background:rgba(0,0,0,.62)!important;box-shadow:0 16px 44px rgba(0,0,0,.48)!important;-webkit-backdrop-filter:blur(8px)!important;backdrop-filter:blur(8px)!important;pointer-events:none!important}
.br-play-circle{width:60px!important;height:60px!important;margin:-30px 0 0 -30px!important}.br-center-play{width:72px!important;height:72px!important;margin:-40px 0 0 -36px!important;transition:transform .08s cubic-bezier(.22,1,.36,1),opacity .08s ease!important}
.br-play-triangle,.br-small-triangle{display:block!important;width:0!important;height:0!important;border-top:9px solid transparent!important;border-bottom:9px solid transparent!important;border-left:14px solid #fff!important;transform:translateX(2px)!important}.br-small-triangle{border-top-width:6px!important;border-bottom-width:6px!important;border-left-width:10px!important}
.br-duration{position:absolute!important;right:9px!important;bottom:9px!important;z-index:4!important;padding:4px 7px!important;border:1px solid rgba(255,255,255,.14)!important;border-radius:6px!important;background:rgba(0,0,0,.80)!important;color:#fff!important;font-size:11px!important;font-weight:800!important;line-height:1!important}
.br-card-info{display:grid!important;grid-template-columns:30px minmax(0,1fr)!important;gap:9px!important;padding:11px 2px 0!important}.br-serial{padding-top:2px!important;color:#575757!important;font-size:12px!important;font-weight:850!important;letter-spacing:.08em!important}.br-serial:before{content:counter(br-video,decimal-leading-zero)!important}
.br-card-title{margin:0!important;color:#fff!important;font:750 15px/1.36 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;letter-spacing:-.02em!important;display:-webkit-box!important;-webkit-box-orient:vertical!important;-webkit-line-clamp:2!important;overflow:hidden!important}.br-card-title a,.br-card-title a:visited,.br-card-title a:hover{color:#fff!important;text-decoration:none!important}
.br-card-meta,.br-player-meta{margin-top:5px!important;color:#969696!important;font-size:12px!important;line-height:1.4!important}
.br-player-post{width:100%!important;max-width:900px!important;margin:0 auto!important}.br-player-shell{border-radius:17px!important;box-shadow:0 28px 85px rgba(0,0,0,.52)!important}.br-player-shade{background:linear-gradient(to bottom,rgba(0,0,0,.08),transparent 42%,rgba(0,0,0,.77))!important}
.br-player-button{position:absolute!important;left:0!important;right:0!important;top:0!important;bottom:0!important;z-index:5!important;width:100%!important;height:100%!important;padding:0!important;border:0!important;border-radius:inherit!important;background:transparent!important;color:#fff!important;cursor:pointer!important;-webkit-tap-highlight-color:transparent!important}.br-player-button:active .br-center-play{transform:scale(.92)!important}
.br-controls{position:absolute!important;left:11px!important;right:11px!important;bottom:10px!important;z-index:4!important;display:grid!important;grid-template-columns:18px auto 1fr auto 18px!important;align-items:center!important;gap:8px!important;color:#fff!important;pointer-events:none!important;filter:drop-shadow(0 2px 5px rgba(0,0,0,.58))!important}.br-control-play{display:grid!important;place-items:center!important;width:18px!important;height:18px!important}.br-current-time,.br-total-time{font-size:10px!important;font-weight:750!important;white-space:nowrap!important}.br-timeline{position:relative!important;height:4px!important;border-radius:20px!important;background:rgba(255,255,255,.35)!important}.br-timeline-fill{position:absolute!important;left:0!important;top:0!important;bottom:0!important;width:2%!important;border-radius:20px!important;background:#fff!important}.br-timeline-fill:after{content:""!important;position:absolute!important;right:-4px!important;top:50%!important;width:8px!important;height:8px!important;margin-top:-4px!important;border-radius:50%!important;background:#fff!important}.br-volume{display:grid!important;place-items:center!important;width:18px!important;height:18px!important;font-size:14px!important}
.br-loader{position:absolute!important;left:50%!important;top:50%!important;z-index:6!important;width:42px!important;height:42px!important;margin:-25px 0 0 -21px!important;border:3px solid rgba(255,255,255,.22)!important;border-top-color:#fff!important;border-radius:50%!important;opacity:0!important;pointer-events:none!important}.br-opening .br-loader{opacity:1!important;animation:br-spin .7s linear infinite!important}.br-opening .br-center-play{opacity:0!important;transform:scale(.8)!important}.br-opening .br-media img{filter:brightness(.64)!important}@keyframes br-spin{to{transform:rotate(360deg)}}
.br-player-copy{padding:17px 2px 0!important}.br-player-title{margin:0!important;color:#fff!important;font:800 clamp(22px,5.5vw,32px)/1.22 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;letter-spacing:-.035em!important;overflow-wrap:anywhere!important}.br-player-meta{display:flex!important;align-items:center!important;gap:7px!important;margin-top:9px!important;font-size:13px!important}.br-meta-dot{color:#555!important}
.br-no-link-note{display:none!important;margin-top:13px!important;padding:10px 12px!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:10px!important;background:#141414!important;color:#aaa!important;font-size:12px!important;line-height:1.45!important}.br-no-link .br-no-link-note{display:block!important}
.br-source-body,.br-raw-labels{display:none!important}.br-smartlink-anchor{display:none!important}.no-posts-message{padding:70px 16px!important;color:#777!important;text-align:center!important}
#blog-pager{display:flex!important;justify-content:center!important;margin:34px 0 0!important}#blog-pager a{min-height:42px!important;padding:0 18px!important;display:inline-flex!important;align-items:center!important;justify-content:center!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:999px!important;background:#141414!important;color:#bbb!important;font-size:13px!important;font-weight:700!important;text-decoration:none!important}
@media(min-width:760px){main.centered-bottom,body.item-view main.centered-bottom{padding-left:22px!important;padding-right:22px!important}body:not(.item-view) .Blog .blog-posts{grid-template-columns:repeat(2,minmax(0,1fr))!important;gap:34px 22px!important}}
@media(max-width:480px){.centered-top{padding:0 58px!important}.Header h1{font-size:18px!important}.Header h1:before{width:30px!important;height:24px!important}main.centered-bottom,body.item-view main.centered-bottom{padding:77px 11px 36px!important}.br-thumb{border-radius:13px!important}.br-player-shell{border-radius:12px!important}.br-center-play{width:62px!important;height:62px!important;margin:-35px 0 0 -31px!important}.br-controls{left:9px!important;right:9px!important;bottom:8px!important;gap:6px!important}}
@media(prefers-reduced-motion:reduce){*,*:before,*:after{animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}



/* ================================================================
   BuzzReelC v3 — compact ModVault-inspired video list
   Internal labels New / Popular / Trending affect seeded metadata only.
   ================================================================ */
.Blog .blog-posts{
  width:100%!important;
  max-width:720px!important;
  margin:0 auto!important;
  grid-template-columns:minmax(0,1fr)!important;
  gap:10px!important;
}
.br-video-card{
  position:relative!important;
  display:grid!important;
  grid-template-columns:minmax(132px,42%) minmax(0,1fr)!important;
  align-items:center!important;
  gap:12px!important;
  width:100%!important;
  min-height:101px!important;
  padding:10px!important;
  overflow:hidden!important;
  border:1px solid rgba(255,255,255,.075)!important;
  border-radius:14px!important;
  background:#151515!important;
  box-shadow:0 7px 24px rgba(0,0,0,.18)!important;
  transition:transform .08s cubic-bezier(.22,1,.36,1),background .08s ease,border-color .08s ease!important;
}
.br-video-card:hover{
  background:#1a1a1a!important;
  border-color:rgba(255,255,255,.11)!important;
}
.br-video-card:active{
  transform:scale(.982)!important;
  background:#1d1d1d!important;
  transition-duration:.08s!important;
}
.br-thumb-link{
  min-width:0!important;
  align-self:center!important;
}
.br-thumb{
  width:100%!important;
  height:0!important;
  padding-top:56.25%!important;
  border-radius:10px!important;
  border-color:rgba(255,255,255,.09)!important;
  box-shadow:none!important;
}
.br-thumb-link:active .br-thumb{
  transform:none!important;
}
.br-card-info{
  display:block!important;
  min-width:0!important;
  padding:0 2px 0 0!important;
}
.br-serial{
  display:none!important;
}
.br-card-title{
  margin:0 0 7px!important;
  color:#f7f7f7!important;
  font:750 15.5px/1.32 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:-.018em!important;
  -webkit-line-clamp:2!important;
}
.br-card-meta{
  display:flex!important;
  align-items:center!important;
  flex-wrap:wrap!important;
  gap:6px!important;
  min-height:17px!important;
  margin:0!important;
  color:#8c8c8c!important;
  font-size:12.5px!important;
  line-height:1.35!important;
}
.br-card-dot{
  color:#4e4e4e!important;
  font-size:10px!important;
}
.br-duration{
  right:6px!important;
  bottom:6px!important;
  padding:4px 6px!important;
  border:0!important;
  border-radius:5px!important;
  background:rgba(0,0,0,.82)!important;
  font-size:10.5px!important;
  letter-spacing:.01em!important;
  box-shadow:0 2px 9px rgba(0,0,0,.30)!important;
}
.br-player-post{
  max-width:820px!important;
}
.br-player-copy{
  padding:14px 3px 0!important;
}
.br-player-title{
  font-size:clamp(21px,5vw,27px)!important;
  line-height:1.22!important;
  letter-spacing:-.026em!important;
}
.br-player-meta{
  margin-top:7px!important;
  color:#8f8f8f!important;
  font-size:12.5px!important;
}
.br-no-link-note{
  display:none!important;
}
@media(min-width:900px){
  .Blog .blog-posts{
    max-width:980px!important;
    grid-template-columns:repeat(2,minmax(0,1fr))!important;
    gap:12px!important;
  }
}
@media(max-width:380px){
  .br-video-card{
    grid-template-columns:126px minmax(0,1fr)!important;
    gap:10px!important;
    padding:9px!important;
  }
  .br-card-title{
    font-size:14.5px!important;
  }
  .br-card-meta{
    font-size:12px!important;
  }
}


/* ================================================================
   BuzzReelC v4 — refined compact feed + modern video player
   - Small homepage play control
   - Cleaner list hierarchy
   - Translucent, rounded and less intrusive player control dock
   ================================================================ */
:root{
  --br-v4-header:58px;
  --br-v4-card:#111111;
  --br-v4-card-hover:#171717;
  --br-v4-line:rgba(255,255,255,.085);
  --br-v4-muted:#949494;
}

/* Compact app-like header without dominating the video content. */
.centered-top-container,
.centered-top-container.sticky{
  height:var(--br-v4-header)!important;
  background:rgba(7,7,7,.90)!important;
  border-bottom-color:rgba(255,255,255,.075)!important;
  -webkit-backdrop-filter:blur(20px) saturate(125%)!important;
  backdrop-filter:blur(20px) saturate(125%)!important;
}
.centered-top{
  height:var(--br-v4-header)!important;
  min-height:var(--br-v4-header)!important;
  padding:0 56px!important;
}
.Header h1{
  font-size:17.5px!important;
  font-weight:760!important;
  letter-spacing:-.03em!important;
}
.Header h1:before{
  width:29px!important;
  height:23px!important;
  margin-right:9px!important;
  border-radius:8px!important;
}
.return_link{
  left:12px!important;
  width:38px!important;
  height:38px!important;
  margin-top:-19px!important;
  border-color:rgba(255,255,255,.09)!important;
  background:rgba(255,255,255,.045)!important;
  box-shadow:0 7px 20px rgba(0,0,0,.24)!important;
}
.return_link .back-button{
  width:20px!important;
  height:20px!important;
}
main.centered-bottom,
body.item-view main.centered-bottom{
  padding-top:calc(var(--br-v4-header) + 14px)!important;
}

/* Homepage: compact video rows inspired by a media library, not giant tiles. */
body:not(.item-view) .Blog .blog-posts{
  width:100%!important;
  max-width:780px!important;
  margin:0 auto!important;
  grid-template-columns:minmax(0,1fr)!important;
  gap:9px!important;
}
.br-video-card{
  display:grid!important;
  grid-template-columns:clamp(126px,38vw,166px) minmax(0,1fr)!important;
  align-items:center!important;
  gap:11px!important;
  min-height:0!important;
  padding:8px!important;
  border:1px solid var(--br-v4-line)!important;
  border-radius:12px!important;
  background:var(--br-v4-card)!important;
  box-shadow:none!important;
}
.br-video-card:hover{
  background:var(--br-v4-card-hover)!important;
  border-color:rgba(255,255,255,.12)!important;
}
.br-video-card:active{
  transform:scale(.985)!important;
  background:#191919!important;
}
.br-thumb{
  border-radius:9px!important;
  border-color:rgba(255,255,255,.075)!important;
  background:#171717!important;
}
.br-thumb-shade{
  background:linear-gradient(to bottom,rgba(0,0,0,.015),transparent 56%,rgba(0,0,0,.38))!important;
}
/* The homepage control is intentionally much smaller than the player-page control. */
.br-video-card .br-play-circle{
  width:34px!important;
  height:34px!important;
  margin:-17px 0 0 -17px!important;
  border-color:rgba(255,255,255,.25)!important;
  background:rgba(5,5,5,.64)!important;
  box-shadow:0 7px 20px rgba(0,0,0,.36)!important;
  -webkit-backdrop-filter:blur(7px)!important;
  backdrop-filter:blur(7px)!important;
}
.br-video-card .br-play-triangle{
  border-top-width:6px!important;
  border-bottom-width:6px!important;
  border-left-width:10px!important;
  transform:translateX(1.5px)!important;
}
.br-duration{
  right:5px!important;
  bottom:5px!important;
  padding:3px 5px!important;
  border:0!important;
  border-radius:4px!important;
  background:rgba(0,0,0,.78)!important;
  box-shadow:0 2px 8px rgba(0,0,0,.28)!important;
  font-size:10px!important;
  font-weight:750!important;
  letter-spacing:.01em!important;
}
.br-card-info{
  display:block!important;
  min-width:0!important;
  padding:0 3px 0 0!important;
}
.br-card-title{
  margin:0 0 6px!important;
  color:#f5f5f5!important;
  font:710 15px/1.31 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:-.016em!important;
  -webkit-line-clamp:2!important;
}
.br-card-meta{
  display:block!important;
  min-height:16px!important;
  margin:0!important;
  color:var(--br-v4-muted)!important;
  font-size:12.25px!important;
  line-height:1.3!important;
}
/* Duration remains visible on the thumbnail, avoiding duplicated metadata outside it. */
.br-card-dot,
.br-card-duration-text{
  display:none!important;
}

/* Player page: clean video-first presentation. */
.br-player-post{
  width:100%!important;
  max-width:920px!important;
  margin:0 auto!important;
}
.br-player-shell{
  border:1px solid rgba(255,255,255,.115)!important;
  border-radius:16px!important;
  background:#101010!important;
  box-shadow:0 24px 70px rgba(0,0,0,.42)!important;
}
.br-player-shade{
  background:
    linear-gradient(to bottom,rgba(0,0,0,.015) 0%,transparent 54%,rgba(0,0,0,.48) 100%),
    radial-gradient(circle at 50% 44%,transparent 48%,rgba(0,0,0,.08) 100%)!important;
}
.br-center-play{
  width:70px!important;
  height:70px!important;
  margin:-39px 0 0 -35px!important;
  border-color:rgba(255,255,255,.28)!important;
  background:rgba(5,5,5,.62)!important;
  box-shadow:0 17px 48px rgba(0,0,0,.44)!important;
  -webkit-backdrop-filter:blur(12px)!important;
  backdrop-filter:blur(12px)!important;
}
/* Rounded translucent control dock: less obstruction, clearer grouping. */
.br-controls{
  left:12px!important;
  right:12px!important;
  bottom:11px!important;
  height:44px!important;
  display:flex!important;
  grid-template-columns:none!important;
  align-items:center!important;
  gap:9px!important;
  padding:0 11px!important;
  border:1px solid rgba(255,255,255,.13)!important;
  border-radius:14px!important;
  background:rgba(12,12,12,.64)!important;
  box-shadow:0 10px 28px rgba(0,0,0,.26)!important;
  -webkit-backdrop-filter:blur(16px) saturate(120%)!important;
  backdrop-filter:blur(16px) saturate(120%)!important;
  filter:none!important;
}
.br-control-play,
.br-fullscreen{
  width:27px!important;
  height:27px!important;
  flex:0 0 27px!important;
  display:grid!important;
  place-items:center!important;
  border:1px solid rgba(255,255,255,.09)!important;
  border-radius:50%!important;
  background:rgba(255,255,255,.09)!important;
  color:#fff!important;
}
.br-controls .br-small-triangle{
  border-top-width:5px!important;
  border-bottom-width:5px!important;
  border-left-width:8px!important;
  transform:translateX(1px)!important;
}
.br-current-time,
.br-total-time{
  flex:0 0 auto!important;
  color:rgba(255,255,255,.90)!important;
  font-size:10.75px!important;
  font-weight:680!important;
  letter-spacing:.01em!important;
}
.br-total-time{
  color:rgba(255,255,255,.72)!important;
}
.br-timeline{
  position:relative!important;
  flex:1 1 auto!important;
  min-width:36px!important;
  height:3px!important;
  border-radius:999px!important;
  background:rgba(255,255,255,.30)!important;
  overflow:hidden!important;
}
.br-timeline-fill{
  width:0!important;
  border-radius:inherit!important;
  background:#fff!important;
}
.br-timeline-fill:after{
  display:none!important;
}
.br-fullscreen svg{
  display:block!important;
}
.br-player-copy{
  padding:16px 3px 0!important;
}
.br-player-title{
  margin:0!important;
  color:#f7f7f7!important;
  font:740 clamp(21px,5vw,28px)/1.2 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:-.028em!important;
}
.br-player-meta{
  display:flex!important;
  align-items:center!important;
  gap:7px!important;
  margin-top:8px!important;
  color:#929292!important;
  font-size:12.75px!important;
  line-height:1.35!important;
}
.br-no-link-note{
  display:none!important;
}

@media(min-width:860px){
  body:not(.item-view) .Blog .blog-posts{
    max-width:1060px!important;
    grid-template-columns:repeat(2,minmax(0,1fr))!important;
    gap:10px!important;
  }
  .br-video-card{
    grid-template-columns:160px minmax(0,1fr)!important;
  }
}
@media(max-width:480px){
