  }
  .br-controls{
    left:8px!important;
    right:8px!important;
    bottom:8px!important;
    height:40px!important;
    gap:7px!important;
    padding:0 9px!important;
    border-radius:12px!important;
  }
  .br-control-play,
  .br-fullscreen{
    width:25px!important;
    height:25px!important;
    flex-basis:25px!important;
  }
  .br-current-time,
  .br-total-time{
    font-size:10.25px!important;
  }
  .br-player-copy{
    padding:14px 2px 0!important;
  }
  .br-player-title{
    font-size:21.5px!important;
  }
}
@media(max-width:350px){
  .br-video-card{
    grid-template-columns:118px minmax(0,1fr)!important;
  }
  .br-controls{
    gap:6px!important;
    padding:0 8px!important;
  }
  .br-current-time{
    display:none!important;
  }
}


/* ================================================================
   BuzzReelC v5 — realistic watch page + resilient seeded metadata
   - Video-first player chrome inspired by major streaming players
   - No duplicate views/duration under the player title
   - Seed values are reapplied after Blogger async DOM updates
   ================================================================ */

/* Keep the compact V4 homepage, but make its metadata feel quieter. */
.br-video-card .br-card-meta{
  color:#8f8f8f!important;
  font-size:12px!important;
  font-weight:500!important;
  letter-spacing:-.005em!important;
}
.br-video-card .br-card-meta,
.br-video-card .br-duration,
.br-player-post .br-total-time{
  transition:opacity .18s ease!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-card-meta,
.br-video-card:not([data-br-meta-ready='1']) .br-duration,
.br-player-post:not([data-br-meta-ready='1']) .br-total-time{
  opacity:0!important;
}

/* Watch page: let the poster dominate and place controls in a native-looking bottom overlay. */
body.item-view main.centered-bottom{
  padding-left:0!important;
  padding-right:0!important;
}
.br-player-post{
  width:100%!important;
  max-width:980px!important;
  margin:0 auto!important;
}
.br-player-shell{
  border:0!important;
  border-radius:0!important;
  background:#000!important;
  box-shadow:none!important;
}
.br-player-shade{
  z-index:2!important;
  background:
    linear-gradient(to bottom,rgba(0,0,0,.08) 0%,transparent 42%,rgba(0,0,0,.12) 58%,rgba(0,0,0,.78) 100%),
    radial-gradient(circle at 50% 45%,transparent 54%,rgba(0,0,0,.10) 100%)!important;
}
.br-center-play{
  z-index:6!important;
  width:72px!important;
  height:72px!important;
  margin:-36px 0 0 -36px!important;
  border:1px solid rgba(255,255,255,.30)!important;
  background:rgba(5,5,5,.62)!important;
  box-shadow:0 16px 48px rgba(0,0,0,.48),inset 0 0 0 1px rgba(0,0,0,.18)!important;
  -webkit-backdrop-filter:blur(13px) saturate(120%)!important;
  backdrop-filter:blur(13px) saturate(120%)!important;
}
.br-player-button:active .br-center-play{
  transform:scale(.92)!important;
}

/* Standard player structure: seek line on top, controls below, no large floating dock. */
.br-controls{
  left:0!important;
  right:0!important;
  bottom:0!important;
  z-index:5!important;
  height:auto!important;
  display:block!important;
  padding:0 14px 10px!important;
  border:0!important;
  border-radius:0!important;
  background:transparent!important;
  box-shadow:none!important;
  -webkit-backdrop-filter:none!important;
  backdrop-filter:none!important;
  filter:drop-shadow(0 2px 5px rgba(0,0,0,.62))!important;
  pointer-events:none!important;
}
.br-progress-row{
  width:100%!important;
  height:14px!important;
  display:flex!important;
  align-items:center!important;
}
.br-timeline{
  position:relative!important;
  display:block!important;
  width:100%!important;
  min-width:0!important;
  height:3px!important;
  overflow:hidden!important;
  border-radius:999px!important;
  background:rgba(255,255,255,.30)!important;
}
.br-timeline-buffer{
  position:absolute!important;
  inset:0 auto 0 0!important;
  width:18%!important;
  border-radius:inherit!important;
  background:rgba(255,255,255,.24)!important;
}
.br-timeline-fill{
  position:absolute!important;
  inset:0 auto 0 0!important;
  width:0!important;
  border-radius:inherit!important;
  background:#fff!important;
}
.br-timeline-fill:after{
  display:none!important;
}
.br-control-row{
  min-height:34px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:space-between!important;
  gap:10px!important;
}
.br-controls-left,
.br-controls-right{
  display:flex!important;
  align-items:center!important;
  gap:7px!important;
  min-width:0!important;
}
.br-control-icon{
  width:32px!important;
  height:32px!important;
  flex:0 0 32px!important;
  display:grid!important;
  place-items:center!important;
  border:1px solid rgba(255,255,255,.10)!important;
  border-radius:50%!important;
  background:rgba(8,8,8,.38)!important;
  color:#fff!important;
  -webkit-backdrop-filter:blur(9px)!important;
  backdrop-filter:blur(9px)!important;
}
.br-control-icon svg{
  display:block!important;
}
.br-control-play .br-small-triangle{
  border-top-width:5px!important;
  border-bottom-width:5px!important;
  border-left-width:8px!important;
  transform:translateX(1px)!important;
}
.br-timecode{
  display:inline-flex!important;
  align-items:center!important;
  gap:4px!important;
  min-width:0!important;
  color:rgba(255,255,255,.92)!important;
  font-size:11px!important;
  font-weight:650!important;
  letter-spacing:.005em!important;
  white-space:nowrap!important;
}
.br-time-separator{
  color:rgba(255,255,255,.42)!important;
}
.br-current-time,
.br-total-time{
  color:inherit!important;
  font:inherit!important;
}
.br-hd-badge{
  height:23px!important;
  padding:0 6px!important;
  display:inline-flex!important;
  align-items:center!important;
  justify-content:center!important;
  border:1px solid rgba(255,255,255,.13)!important;
  border-radius:6px!important;
  background:rgba(8,8,8,.38)!important;
  color:rgba(255,255,255,.92)!important;
  font-size:9px!important;
  font-weight:800!important;
  letter-spacing:.06em!important;
  -webkit-backdrop-filter:blur(9px)!important;
  backdrop-filter:blur(9px)!important;
}

/* Only the title remains below the video. */
.br-player-copy{
  padding:15px 16px 0!important;
}
.br-player-title{
  margin:0!important;
  color:#f5f5f5!important;
  font:720 clamp(20px,4.8vw,27px)/1.24 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:-.026em!important;
  overflow-wrap:anywhere!important;
}
.br-player-meta,
.br-meta-dot,
.br-duration-text{
  display:none!important;
}
.br-no-link-note{
  display:none!important;
}

@media(min-width:700px){
  body.item-view main.centered-bottom{
    padding-left:22px!important;
    padding-right:22px!important;
  }
  .br-player-shell{
    border:1px solid rgba(255,255,255,.10)!important;
    border-radius:16px!important;
    box-shadow:0 28px 82px rgba(0,0,0,.48)!important;
  }
  .br-controls{
    padding-left:16px!important;
    padding-right:16px!important;
    padding-bottom:12px!important;
  }
  .br-player-copy{
    padding-left:3px!important;
    padding-right:3px!important;
  }
}

@media(max-width:480px){
  .br-center-play{
    width:66px!important;
    height:66px!important;
    margin:-33px 0 0 -33px!important;
  }
  .br-controls{
    padding:0 9px 7px!important;
  }
  .br-progress-row{
    height:12px!important;
  }
  .br-control-row{
    min-height:31px!important;
  }
  .br-control-icon{
    width:29px!important;
    height:29px!important;
    flex-basis:29px!important;
  }
  .br-controls-left,
  .br-controls-right{
    gap:5px!important;
  }
  .br-timecode{
    font-size:10.5px!important;
  }
  .br-hd-badge{
    height:21px!important;
    padding:0 5px!important;
    font-size:8px!important;
  }
  .br-player-copy{
    padding:14px 13px 0!important;
  }
  .br-player-title{
    font-size:21px!important;
  }
}

@media(max-width:355px){
  .br-settings,
  .br-hd-badge{
    display:none!important;
  }
}


/* ================================================================
   BuzzReelC v6 — compact homepage + minimal player + CSS seed fallback
   - Homepage center play is exactly 34px
   - Watch page keeps center Play, thin timeline, time, volume, fullscreen
   - Post-ID suffix and internal label classes provide deterministic fallback
   ================================================================ */
.br-video-card,.br-player-post{
  --br-fallback-views:"1.39M views";
  --br-fallback-duration:"4:58";
}
.br-play-circle{
  width:34px!important;
  height:34px!important;
  margin:-17px 0 0 -17px!important;
  border-width:1px!important;
  box-shadow:0 8px 22px rgba(0,0,0,.42)!important;
}
.br-play-circle .br-play-triangle{
  border-top-width:5px!important;
  border-bottom-width:5px!important;
  border-left-width:8px!important;
  transform:translateX(1px)!important;
}
.br-control-play,.br-hd-badge,.br-settings{
  display:none!important;
}
.br-timeline{
  height:2px!important;
}
.br-player-meta,.br-meta-dot,.br-duration-text,
.br-raw-labels,.byline.post-labels,.post-labels,.widget.Label{
  display:none!important;
}
/* V5 hid metadata until JavaScript finished. V6 always shows a seeded fallback. */
.br-video-card:not([data-br-meta-ready='1']) .br-card-meta,
.br-video-card:not([data-br-meta-ready='1']) .br-duration,
.br-player-post:not([data-br-meta-ready='1']) .br-total-time{
  opacity:1!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-views,
.br-video-card:not([data-br-meta-ready='1']) .br-card-duration-text,
.br-video-card:not([data-br-meta-ready='1']) .br-duration,
.br-player-post:not([data-br-meta-ready='1']) .br-total-time{
  position:relative!important;
  color:transparent!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-views:after,
.br-video-card:not([data-br-meta-ready='1']) .br-card-duration-text:after,
.br-video-card:not([data-br-meta-ready='1']) .br-duration:after,
.br-player-post:not([data-br-meta-ready='1']) .br-total-time:after{
  position:absolute!important;
  left:0!important;
  top:0!important;
  color:inherit!important;
  white-space:nowrap!important;
  pointer-events:none!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-views:after{
  content:var(--br-fallback-views)!important;
  color:#8f8f8f!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-card-duration-text:after{
  content:var(--br-fallback-duration)!important;
  color:#8f8f8f!important;
}
.br-video-card:not([data-br-meta-ready='1']) .br-duration:after{
  content:var(--br-fallback-duration)!important;
  inset:0!important;
  display:grid!important;
  place-items:center!important;
  color:#fff!important;
  background:rgba(0,0,0,.80)!important;
  border-radius:inherit!important;
}
.br-player-post:not([data-br-meta-ready='1']) .br-total-time:after{
  content:var(--br-fallback-duration)!important;
  color:rgba(255,255,255,.92)!important;
}
.br-video-card[data-br-key$='0'],.br-player-post[data-br-key$='0']{--br-fallback-views:"678K views";}
.br-video-card[data-br-key$='1'],.br-player-post[data-br-key$='1']{--br-fallback-views:"742K views";}
.br-video-card[data-br-key$='2'],.br-player-post[data-br-key$='2']{--br-fallback-views:"816K views";}
.br-video-card[data-br-key$='3'],.br-player-post[data-br-key$='3']{--br-fallback-views:"893K views";}
.br-video-card[data-br-key$='4'],.br-player-post[data-br-key$='4']{--br-fallback-views:"967K views";}
.br-video-card[data-br-key$='5'],.br-player-post[data-br-key$='5']{--br-fallback-views:"1M views";}
.br-video-card[data-br-key$='6'],.br-player-post[data-br-key$='6']{--br-fallback-views:"1.1M views";}
.br-video-card[data-br-key$='7'],.br-player-post[data-br-key$='7']{--br-fallback-views:"1.2M views";}
.br-video-card[data-br-key$='8'],.br-player-post[data-br-key$='8']{--br-fallback-views:"1.3M views";}
.br-video-card[data-br-key$='9'],.br-player-post[data-br-key$='9']{--br-fallback-views:"1.39M views";}
.br-status-new[data-br-key$='0']{--br-fallback-views:"534K views";}
.br-status-new[data-br-key$='1']{--br-fallback-views:"587K views";}
.br-status-new[data-br-key$='2']{--br-fallback-views:"631K views";}
.br-status-new[data-br-key$='3']{--br-fallback-views:"684K views";}
.br-status-new[data-br-key$='4']{--br-fallback-views:"728K views";}
.br-status-new[data-br-key$='5']{--br-fallback-views:"771K views";}
.br-status-new[data-br-key$='6']{--br-fallback-views:"815K views";}
.br-status-new[data-br-key$='7']{--br-fallback-views:"858K views";}
.br-status-new[data-br-key$='8']{--br-fallback-views:"903K views";}
