/* ================================================================
   BuzzReelC v6.1 — right-side Back control + reliable single-tap UI
   - Video-page brand is left aligned; Back is a polished right-side pill
   - Removes nested interactive markup from Back control
   - Entire homepage card is one deterministic link hit area
   - touch-action removes legacy tap delay; player redirect delay is minimal
   ================================================================ */
a,button,.return_link,.br-card-hit-target,.br-player-button{
  -webkit-tap-highlight-color:transparent!important;
  touch-action:manipulation!important;
}
body.item-view .centered-top{
  justify-content:flex-start!important;
  padding:0 101px 0 13px!important;
}
body.item-view .blog-name,
body.item-view.collapsed-header .centered-top-container .blog-name,
body.item-view .centered-top-container .blog-name{
  position:static!important;
  flex:1 1 auto!important;
  width:100%!important;
  max-width:100%!important;
  min-width:0!important;
  margin:0!important;
  padding:0!important;
  display:flex!important;
  align-items:center!important;
  justify-content:flex-start!important;
  flex-wrap:nowrap!important;
  overflow:hidden!important;
}
body.item-view #header,
body.item-view .widget.Header,
body.item-view .header-widget{
  width:100%!important;
  min-width:0!important;
}
body.item-view .Header h1,
body.item-view .sticky .Header h1{
  width:100%!important;
  min-width:0!important;
  max-width:100%!important;
  justify-content:flex-start!important;
  text-align:left!important;
  overflow:hidden!important;
}
body.item-view .Header h1 a{
  min-width:0!important;
  max-width:calc(100vw - 158px)!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
}
body.item-view .return_link{
  left:auto!important;
  right:11px!important;
  top:50%!important;
  z-index:30!important;
  width:78px!important;
  height:38px!important;
  min-width:78px!important;
  margin:-19px 0 0!important;
  padding:0 12px 0 10px!important;
  display:flex!important;
  align-items:center!important;
  justify-content:center!important;
  gap:6px!important;
  overflow:hidden!important;
  border:1px solid rgba(255,255,255,.13)!important;
  border-radius:12px!important;
  background:linear-gradient(180deg,rgba(255,255,255,.105),rgba(255,255,255,.045))!important;
  color:#f4f4f4!important;
  box-shadow:0 8px 24px rgba(0,0,0,.30),inset 0 1px 0 rgba(255,255,255,.055)!important;
  text-decoration:none!important;
  cursor:pointer!important;
  -webkit-user-select:none!important;
  user-select:none!important;
  transition:transform .08s ease,background .08s ease,border-color .08s ease!important;
}
body.item-view .return_link .br-back-icon{
  width:18px!important;
  height:18px!important;
  flex:0 0 18px!important;
  display:block!important;
  color:currentColor!important;
}
body.item-view .return_link .br-back-label{
  display:block!important;
  color:inherit!important;
  font:720 12.5px/1 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:-.01em!important;
  white-space:nowrap!important;
}
body.item-view .return_link:active{
  transform:scale(.95)!important;
  background:rgba(255,255,255,.14)!important;
}
body.item-view .return_link:focus-visible,
.br-card-hit-target:focus-visible,
.br-player-button:focus-visible{
  outline:2px solid rgba(255,255,255,.94)!important;
  outline-offset:2px!important;
}
@media(hover:hover) and (pointer:fine){
  body.item-view .return_link:hover{
    transform:translateY(-1px)!important;
    border-color:rgba(255,255,255,.20)!important;
    background:linear-gradient(180deg,rgba(255,255,255,.15),rgba(255,255,255,.07))!important;
  }
}
.br-video-card{
  cursor:pointer!important;
  -webkit-user-select:none!important;
  user-select:none!important;
}
.br-card-hit-target{
  position:absolute!important;
  inset:0!important;
  z-index:25!important;
  display:block!important;
  width:auto!important;
  height:auto!important;
  border-radius:inherit!important;
  color:transparent!important;
  text-decoration:none!important;
  cursor:pointer!important;
}
/* The full-card link owns pointer input; visual links remain as readable markup. */
.br-video-card .br-thumb-link,
.br-video-card .br-card-title a{
  pointer-events:none!important;
}
.br-player-button{
  -webkit-user-select:none!important;
  user-select:none!important;
  cursor:pointer!important;
}
@media(max-width:380px){
  body.item-view .centered-top{
    padding-right:58px!important;
  }
  body.item-view .Header h1 a{
    max-width:calc(100vw - 116px)!important;
  }
  body.item-view .return_link{
    width:40px!important;
    min-width:40px!important;
    height:40px!important;
    margin-top:-20px!important;
    padding:0!important;
    border-radius:12px!important;
  }
  body.item-view .return_link .br-back-label{
    display:none!important;
  }
  body.item-view .return_link .br-back-icon{
    width:19px!important;
    height:19px!important;
  }
}
@media(prefers-reduced-motion:reduce){
  .return_link,.br-video-card,.br-thumb,.br-center-play{
    transition:none!important;
  }
}

/* ================================================================
   BuzzReelC v6.3 — unified two-tap flow beside duration
   - Clearly discloses the first advertising tap and second file tap
   - Desktop and mobile use the same clear disclosure wording
   ================================================================ */
.br-controls-left{
  flex:1 1 auto!important;
  overflow:hidden!important;
}
.br-controls-right{
  flex:0 0 auto!important;
}
.br-timecode{
  flex:0 0 auto!important;
}
.br-flow-note{
  flex:0 1 auto!important;
  min-width:0!important;
  max-width:100%!important;
  display:inline-flex!important;
  align-items:center!important;
  overflow:hidden!important;
  padding-left:7px!important;
  margin-left:1px!important;
  border-left:1px solid rgba(255,255,255,.18)!important;
  color:rgba(255,255,255,.74)!important;
  font:600 9.75px/1.15 -apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,Arial,sans-serif!important;
  letter-spacing:.002em!important;
  white-space:nowrap!important;
  text-overflow:ellipsis!important;
}
.br-flow-long,
.br-flow-short{
  min-width:0!important;
  overflow:hidden!important;
  text-overflow:ellipsis!important;
  white-space:nowrap!important;
}
.br-flow-short{
  display:none!important;
}
@media(max-width:400px){
  .br-flow-note{
    padding-left:5px!important;
    font-size:9.25px!important;
  }
  .br-flow-long{
    display:none!important;
  }
  .br-flow-short{
    display:inline!important;
  }
}
@media(max-width:330px){
  .br-controls{
    padding-left:7px!important;
    padding-right:7px!important;
  }
  .br-controls-left,
  .br-controls-right{
    gap:4px!important;
  }
  .br-flow-note{
    font-size:8.7px!important;
  }
}




@supports (content-visibility:auto){
  .br-video-card{content-visibility:auto!important;contain-intrinsic-size:auto 300px!important}
}


/* ================================================================
   BuzzReelC v9.1 — isolated monotonic 18+ warning
   Hidden by default; only the initial br-age-required decision can show it.
   After acceptance no later event is permitted to downgrade the document.
   ================================================================ */
.br-age-gate{position:fixed!important;inset:0!important;z-index:2147483646!important;display:none!important;align-items:center!important;justify-content:center!important;padding:20px!important;background:radial-gradient(circle at 18% 12%,rgba(255,72,72,.16),transparent 34%),radial-gradient(circle at 82% 88%,rgba(108,92,231,.14),transparent 38%),rgba(3,3,4,.94)!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important;overscroll-behavior:contain!important}
/* v12.1 Blogger-safe state: hidden by default; only explicit required state can show it. */
.br-age-pass-target{position:fixed!important;top:0!important;left:0!important;width:1px!important;height:1px!important;overflow:hidden!important;opacity:0!important;pointer-events:none!important}
html.br-age-required #br-age-pass + .br-age-gate{display:flex!important;opacity:1!important;visibility:visible!important;pointer-events:auto!important}
#br-age-pass:target + .br-age-gate,html.br-age-accepted #br-age-pass + .br-age-gate{display:none!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important;transition:none!important}
/* The fixed overlay intercepts interaction; scroll lock is not tied to storage availability. */
.br-age-gate:before{content:"";position:absolute!important;inset:0!important;pointer-events:none!important;background-image:linear-gradient(rgba(255,255,255,.018) 1px,transparent 1px),linear-gradient(90deg,rgba(255,255,255,.018) 1px,transparent 1px)!important;background-size:32px 32px!important;mask-image:linear-gradient(to bottom,rgba(0,0,0,.78),transparent)!important}
.br-age-card{position:relative!important;width:min(100%,460px)!important;padding:30px 28px 25px!important;overflow:hidden!important;border:1px solid rgba(255,255,255,.12)!important;border-radius:24px!important;background:linear-gradient(145deg,rgba(27,27,30,.97),rgba(12,12,14,.98))!important;box-shadow:0 35px 100px rgba(0,0,0,.62),inset 0 1px 0 rgba(255,255,255,.05)!important;color:#fff!important;text-align:center!important}
.br-age-badge{width:96px!important;height:96px!important;margin:0 auto 20px!important;display:grid!important;place-items:center!important;border:1px solid rgba(255,96,96,.38)!important;border-radius:50%!important;background:radial-gradient(circle at 36% 28%,#ff6b6b,#d8293f 58%,#8f1025)!important;color:#fff!important;font-size:35px!important;font-weight:900!important;letter-spacing:-.06em!important;box-shadow:0 18px 52px rgba(216,41,63,.28),inset 0 1px 0 rgba(255,255,255,.32)!important}
.br-age-title{margin:0 0 11px!important;color:#fff!important;font-size:27px!important;font-weight:850!important;line-height:1.15!important;letter-spacing:-.045em!important}
.br-age-copy{max-width:370px!important;margin:0 auto 24px!important;color:rgba(255,255,255,.69)!important;font-size:14px!important;line-height:1.62!important}
.br-age-actions{display:grid!important;grid-template-columns:1fr!important;gap:11px!important}
.br-age-enter,.br-age-exit{box-sizing:border-box!important;width:100%!important;min-height:50px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-radius:14px!important;font-family:inherit!important;font-size:14px!important;font-weight:800!important;line-height:1!important;text-decoration:none!important;-webkit-tap-highlight-color:transparent!important;touch-action:manipulation!important;cursor:pointer!important;transition:transform .06s linear,background .06s linear,border-color .06s linear!important}
.br-age-enter{position:relative!important;z-index:5!important;pointer-events:auto!important;-webkit-appearance:none!important;appearance:none!important;border:1px solid rgba(255,255,255,.92)!important;background:#fff!important;color:#09090a!important;box-shadow:0 12px 34px rgba(255,255,255,.10)!important;-webkit-user-select:none!important;user-select:none!important}
.br-age-exit{border:1px solid rgba(255,255,255,.11)!important;background:rgba(255,255,255,.045)!important;color:rgba(255,255,255,.76)!important}
.br-age-enter:hover{background:#f2f2f2!important}.br-age-exit:hover{background:rgba(255,255,255,.085)!important;border-color:rgba(255,255,255,.18)!important}
.br-age-enter:active,.br-age-exit:active{transform:scale(.985)!important}
.br-age-enter:focus-visible,.br-age-exit:focus-visible{outline:2px solid #fff!important;outline-offset:3px!important}
@media (max-width:520px){.br-age-gate{padding:14px!important}.br-age-card{padding:25px 19px 20px!important;border-radius:21px!important}.br-age-badge{width:84px!important;height:84px!important;margin-bottom:17px!important;font-size:31px!important}.br-age-title{font-size:24px!important}.br-age-copy{font-size:13px!important;margin-bottom:21px!important}.br-age-enter,.br-age-exit{min-height:49px!important}}
@media (prefers-reduced-motion:reduce){.br-age-gate,.br-age-enter,.br-age-exit{transition:none!important}}


/* ================================================================
   BuzzReelC v11.4 — Blogger-safe checkbox fallback + self-contained age gate
   Player design and seeded views/duration intentionally unchanged.
   ================================================================ */
.br-visually-hidden{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
.post-filter-message{display:flex!important;align-items:center!important;justify-content:space-between!important;gap:14px!important;margin:0 0 24px!important;padding:13px 15px!important;border:1px solid rgba(255,255,255,.10)!important;border-radius:13px!important;background:#111!important;color:#bbb!important;font-size:13px!important;line-height:1.45!important}
.post-filter-message a{min-height:36px!important;padding:0 13px!important;display:inline-flex!important;align-items:center!important;border:1px solid rgba(255,255,255,.12)!important;border-radius:999px!important;background:rgba(255,255,255,.06)!important;color:#fff!important;text-decoration:none!important;white-space:nowrap!important}
#blog-pager{gap:10px!important;flex-wrap:wrap!important}
#blog-pager a:hover{border-color:rgba(255,255,255,.22)!important;background:#1b1b1b!important;color:#fff!important}
#blog-pager a:focus-visible{outline:2px solid #fff!important;outline-offset:3px!important}
.br-no-link .br-player-button{cursor:not-allowed!important}
@media(max-width:430px){
  .post-filter-message{align-items:flex-start!important;flex-direction:column!important}
}

head.b:template-skin:

body#layout .hidden,
body#layout .invisible {
  display: inherit;
}
body#layout .navigation {
  display: none;
}
body#layout .page,
body#layout .sidebar_top,
body#layout .sidebar_bottom {
  display: inline-block;
  left: inherit;
  position: relative;
  vertical-align: top;
}
body#layout .page {
  float: right;
  margin-left: 20px;
  width: 55%;
}
body#layout .sidebar-container {
  float: right;
  width: 40%;
}
body#layout .hamburger-menu {
  display: none;
}

body.script:
(function(window, document){
  'use strict';
  var HASH = '#br-age-pass';
  var STORAGE_KEY = 'brAgeApprovedAtV1';
  var TTL_MS = 2592000000;
  var root = document.documentElement;
  var body = document.body;
  var gate = document.getElementById('br-age-gate');
  var finalStateApplied = false;

  function report(message, error){
    if(window.console && window.console.warn){ window.console.warn(message, error || ''); }
  }
  function hasClass(name){
    return !!(root && (' ' + String(root.className || '') + ' ').indexOf(' ' + name + ' ') !== -1);
  }
  function addClass(name){
    if(root && !hasClass(name)){ root.className = String(root.className || '') + ' ' + name; }
  }
  function removeClass(name){
    if(root){
      root.className = String(root.className || '')
        .replace(new RegExp('(^|\\s)' + name + '(?=\\s|$)', 'g'), ' ')
        .replace(/^\s+|\s+$/g, '')
        .replace(/\s{2,}/g, ' ');
    }
  }
  function storage(){
    try{ return window.localStorage || null; }
    catch(error){ report('Age approval storage is unavailable; using URL fragment fallback.', error); return null; }
  }
  function clearStoredApproval(target){
    try{ if(target){ target.removeItem(STORAGE_KEY); } }
    catch(error){ report('Unable to clear age approval storage.', error); }
  }
  function validApprovalTime(value){
    var now = new Date().getTime();
    return value > 0 && value <= now && (now - value) <= TTL_MS;
  }
  function storageAccepted(){
    var target = storage();
    var raw;
    var value;
    if(!target){ return false; }
    try{ raw = target.getItem(STORAGE_KEY); }
    catch(error){ report('Unable to read age approval storage; using URL fragment fallback.', error); return false; }
    value = parseInt(raw || '0', 10) || 0;
    if(validApprovalTime(value)){ return true; }
    if(raw){ clearStoredApproval(target); }
    return false;
  }
  function hashAccepted(){
    return String(window.location.hash || '').toLowerCase() === HASH;
  }
  function accepted(){
    return hasClass('br-age-accepted') || storageAccepted() || hashAccepted();
  }
  function persistApproval(){
    var target = storage();
    if(!target){ return false; }
    try{ target.setItem(STORAGE_KEY, String(new Date().getTime())); return true; }
    catch(error){ report('Unable to persist age approval; URL fragment fallback remains active.', error); return false; }
  }
  function setImportant(node, name, value){
    if(node && node.style && node.style.setProperty){ node.style.setProperty(name, value, 'important'); }
  }
  function clearProperty(node, name){
    if(node && node.style && node.style.removeProperty){ node.style.removeProperty(name); }
  }
  function setState(name){
    removeClass('br-age-required');
    removeClass('br-age-accepted');
    addClass(name);
    finalStateApplied = true;
  }
  function hideGate(removeNode){
    if(!gate){ return; }
    gate.setAttribute('aria-hidden', 'true');
    gate.setAttribute('hidden', 'hidden');
    setImportant(gate, 'display', 'none');
    setImportant(gate, 'opacity', '0');
    setImportant(gate, 'visibility', 'hidden');
    setImportant(gate, 'pointer-events', 'none');
    setImportant(gate, 'transition', 'none');
    if(removeNode && gate.parentNode){
      gate.parentNode.removeChild(gate);
      gate = null;
    }
  }
  function showFreshGate(){
    if(!gate){ return; }
    gate.setAttribute('aria-hidden', 'false');
    gate.removeAttribute('hidden');
    clearProperty(gate, 'display');
    clearProperty(gate, 'opacity');
    clearProperty(gate, 'visibility');
    clearProperty(gate, 'pointer-events');
    clearProperty(gate, 'transition');
  }
  function revealDocument(){
    removeClass('br-age-preboot');
    if(body){
      clearProperty(body, 'visibility');
      clearProperty(body, 'opacity');
    }
  }
  function forceLayout(){
    try{ void document.documentElement.offsetHeight; }
    catch(error){ report('Unable to force age-gate layout flush.', error); }
  }
  function writeAcceptedUrl(){
    var clean;
    try{
      clean = String(window.location.href || '').replace(/#.*$/, '') + HASH;
      if(window.history && window.history.replaceState){
        window.history.replaceState(window.history.state, document.title, clean);
      }else{
        window.location.hash = HASH.substring(1);
      }
    }catch(error){
      report('Unable to update age approval URL fragment.', error);
      try{ window.location.hash = HASH.substring(1); }
      catch(hashError){ report('Unable to set age approval hash fallback.', hashError); }
    }
  }
  function closestAnchor(node){
    while(node && node !== document){
      if(node.nodeType === 1 && String(node.tagName || '').toLowerCase() === 'a'){ return node; }
      node = node.parentNode;
    }
    return null;
  }
  function applyAcceptedState(removeNode){
    setState('br-age-accepted');
    hideGate(removeNode);
  }
  function acceptNow(event){
    var anchor = closestAnchor(event && event.target);
    if(!anchor || anchor.id !== 'br-age-enter'){ return; }
    if(event && event.preventDefault){ event.preventDefault(); }
    persistApproval();
    writeAcceptedUrl();
    applyAcceptedState(true);
    forceLayout();
    revealDocument();
  }
  function resolveInitialState(){
    if(accepted()){
      if(hashAccepted()){ persistApproval(); }
      applyAcceptedState(true);
    }else{
      setState('br-age-required');
      showFreshGate();
    }
    forceLayout();
    revealDocument();
  }
  function scrubAcceptedSnapshot(){
    if(accepted()){
      applyAcceptedState(true);
      forceLayout();
    }
  }

  document.addEventListener('click', acceptNow, true);
  try{
    resolveInitialState();
  }catch(error){
    report('Age-gate initialization failed; showing the gate as a safe fallback.', error);
    if(accepted()) {
      applyAcceptedState(true);
    } else {
      setState('br-age-required');
      showFreshGate();
    }
  }finally{
    if(!finalStateApplied){
      if(accepted()) {
        applyAcceptedState(true);
      } else {
        setState('br-age-required');
      }
    }
    revealDocument();
  }

  if(window.addEventListener){
    window.addEventListener('hashchange', function(){
      if(accepted()){ applyAcceptedState(true); }
      forceLayout();
      revealDocument();
    }, false);
    window.addEventListener('pageshow', function(){
      if(accepted()){ applyAcceptedState(true); }
