(function(window, document){
  'use strict';
  var HASH = '#br-age-pass';

  function isAccepted(){
    return String(window.location.hash || '').toLowerCase() === HASH;
  }
  function eligible(anchor){
    var raw;
    var url;
    if(!anchor || !isAccepted()){ return false; }
    if(anchor.id === 'br-age-enter' || anchor.id === 'br-age-exit'){ return false; }
    if(anchor.classList && anchor.classList.contains('br-player-button')){ return false; }
    if(anchor.hasAttribute('download')){ return false; }
    if(anchor.getAttribute('target') === '_blank'){ return false; }
    raw = anchor.getAttribute('href') || '';
    if(!raw || raw.charAt(0) === '#' || /^javascript:/i.test(raw) || /^mailto:/i.test(raw) || /^tel:/i.test(raw)){ return false; }
    try{
      url = new URL(raw, window.location.href);
      return /^https?:$/i.test(url.protocol) && url.origin === window.location.origin;
    }catch(ignoreUrl){ return false; }
  }
  function carry(anchor){
    var url;
    if(!eligible(anchor)){ return; }
    try{
      url = new URL(anchor.getAttribute('href') || anchor.href, window.location.href);
      url.hash = HASH.substring(1);
      anchor.setAttribute('href', url.href);
    }catch(ignoreCarry){}
  }
  function upgrade(root){
    var links;
    var i;
    if(!isAccepted()){ return; }
    try{ links = (root || document).querySelectorAll('a[href]'); }
    catch(ignoreQuery){ links = []; }
    for(i = 0; i < links.length; i += 1){ carry(links[i]); }
  }
  function closestAnchor(node){
    while(node && node !== document){
      if(node.nodeType === 1 && String(node.tagName || '').toLowerCase() === 'a'){ return node; }
      node = node.parentNode;
    }
    return null;
  }

  document.addEventListener('click', function(event){
    carry(closestAnchor(event && event.target));
  }, true);
  if(document.readyState === 'loading'){
    document.addEventListener('DOMContentLoaded', function(){ upgrade(document); }, false);
  }else{
    upgrade(document);
  }
  if(window.addEventListener){
    window.addEventListener('pageshow', function(){ upgrade(document); }, false);
  }
})(window, document);

/*
 * BuzzReelC v11.0 — safety, privacy and navigation audit: native homepage + isolated one-time video ad.
 * C: video-page two-tap only. D: immutable native content navigation.
 * Popunder state is never read or written here.
 */
var BR_VIDEO_SMARTLINK_URL = 'https://www.effectivecpmnetwork.com/sdkxj7zr5?key=71e7dad94e17a6181e73fe4eb6370bf5';
var BR_ALLOWED_FILE_HOSTS = [
  'terabox.com','1024tera.com','teraboxapp.com','dubox.com',
  'mediafire.com','mega.nz','mega.io','dropbox.com','sendspace.com',
  'pixeldrain.com','gofile.io','drive.google.com','docs.google.com',
