(function(window, document){
  'use strict';
  if(window.__BR_CONTENT_MODULES_V110_STARTED__){ return; }
  window.__BR_CONTENT_MODULES_V110_STARTED__ = true;

  function one(root, selector){ return root ? root.querySelector(selector) : null; }
  function all(root, selector){ return root ? Array.prototype.slice.call(root.querySelectorAll(selector)) : []; }
  function cleanText(value){ return String(value || '').replace(/\s+/g, ' ').replace(/^\s+|\s+$/g, ''); }
  function setText(node, value){
    if(node && cleanText(node.textContent || node.innerText || '') !== String(value)){ node.textContent = value; }
  }
  function hasClass(node, className){
    return !!(node && (' ' + String(node.className || '') + ' ').indexOf(' ' + className + ' ') !== -1);
  }
  function addClass(node, className){
    if(node && !hasClass(node, className)){ node.className += ' ' + className; }
  }
  function removeClass(node, className){
    if(node){ node.className = String(node.className || '').replace(new RegExp('\\s*' + className + '\\b', 'g'), ''); }
  }
  function closestByClass(node, className){
    while(node && node !== document){
      if(hasClass(node, className)){ return node; }
      node = node.parentNode;
    }
    return null;
  }
  function safeUrl(raw){
    var value = cleanText(raw);
    var anchor;
    if(!value){ return ''; }
    try{
      anchor = document.createElement('a');
      anchor.href = value;
      return /^(https?:)$/i.test(anchor.protocol) ? anchor.href : '';
    }catch(ignoreUrl){ return ''; }
  }
  function hash32(value){
    var text = String(value || '');
    var hash = 2166136261;
    var i;
    for(i = 0; i < text.length; i += 1){
      hash ^= text.charCodeAt(i);
      hash += (hash << 1) + (hash << 4) + (hash << 7) + (hash << 8) + (hash << 24);
    }
    return hash >>> 0;
  }
  function seededUnit(key, salt){
    var x = hash32(String(key || '') + '|' + String(salt || '')) || 1;
    x ^= x << 13;
    x ^= x >>> 17;
    x ^= x << 5;
    return (x >>> 0) / 4294967296;
  }
  function postKey(root){
    var nativeKey = cleanText(root.getAttribute('data-br-key') || '');
    var nativeUrl = cleanText(root.getAttribute('data-br-url') || '');
    var titleNode = one(root, '.br-card-title,.br-player-title');
    var title = titleNode ? cleanText(titleNode.textContent || titleNode.innerText || '') : '';
    var link = one(root, '.br-card-title a');
    var url = nativeUrl;
    if(!url && link && link.href){ url = link.href; }
    if(!url){ url = window.location.pathname || window.location.href; }
    return (nativeKey || url || title || 'post') + '|' + String(title || '').toLowerCase();
  }
  function stablePostIdentity(root){
    var nativeKey = root ? cleanText(root.getAttribute('data-br-key') || '') : '';
    var nativeUrl = root ? safeUrl(root.getAttribute('data-br-url') || '') : '';
    var fallback = String(window.location.pathname || window.location.href || 'post').replace(/[?#].*$/, '');
    return nativeKey || nativeUrl || fallback;
  }

  /* Existing fake views/duration algorithm intentionally preserved. */
  function statusFromLabels(root){
    var status = 'default';
    all(root, '.br-raw-label').forEach(function(labelNode){
      var label = cleanText(labelNode.textContent || labelNode.innerText || '').toLowerCase();
      if(label === 'trending'){ status = 'trending'; }
      else if(label === 'popular' && status !== 'trending'){ status = 'popular'; }
      else if(label === 'new' && status === 'default'){ status = 'new'; }
    });
    return status;
  }
  function formatViews(value){
    if(value >= 1000000){
      var millions = Math.round((value / 1000000) * 10) / 10;
      return String(millions).replace(/\.0$/, '') + 'M';
    }
    return String(Math.round(value / 1000)) + 'K';
  }
  function formatDuration(totalSeconds){
    var minutes = Math.floor(totalSeconds / 60);
    var seconds = totalSeconds % 60;
    return String(minutes) + ':' + (seconds < 10 ? '0' : '') + String(seconds);
  }
  function readMeta(root){
    var ranges = {
      'new': [500000, 949000],
      'popular': [950000, 1790000],
      'trending': [1800000, 2990000],
      'default': [650000, 1390000]
    };
    var key = postKey(root);
    var status = statusFromLabels(root);
    var range = ranges[status] || ranges['default'];
    var viewUnit = seededUnit(key, 'views-' + status);
    var rawViews = range[0] + Math.floor(viewUnit * (range[1] - range[0] + 1));
    var durationUnit;
    var seconds;
    var tail;
    rawViews = Math.round(rawViews / 1000) * 1000;
    durationUnit = seededUnit(key, 'duration-v2');
    seconds = 185 + Math.floor(durationUnit * 114);
    tail = seconds % 60;
    if(tail === 0 || tail === 1 || tail === 30 || tail === 59){ seconds += 4; }
    if(seconds > 298){ seconds = 298; }
    return { views: formatViews(rawViews), duration: formatDuration(seconds), status: status };
  }
  function applyMeta(root){
    var meta;
    if(!root){ return; }
    meta = readMeta(root);
    all(root, '.br-views').forEach(function(node){ setText(node, meta.views + ' views'); });
    all(root, '.br-duration,.br-total-time,.br-card-duration-text').forEach(function(node){ setText(node, meta.duration); });
    root.setAttribute('data-br-meta-ready', '1');
    root.setAttribute('data-br-status', meta.status);
  }

  /* Module D v11.0: explicit, allow-listed file destinations only. */
  var NativeContentNavigation = (function(){
    function parts(url){
      var anchor;
      try{
        anchor = document.createElement('a');
        anchor.href = url;
        return {
          host: String(anchor.hostname || '').toLowerCase(),
          path: String(anchor.pathname || '').toLowerCase(),
          href: anchor.href
        };
      }catch(ignoreParts){ return {host:'', path:'', href:''}; }
    }
    function isSmartLink(url){ return safeUrl(url) === safeUrl(BR_VIDEO_SMARTLINK_URL); }
    function isImageUrl(url){
      var value = parts(url);
      return value.host.indexOf('googleusercontent.com') !== -1 ||
             value.host.indexOf('blogger.googleusercontent.com') !== -1 ||
             /(^|\.)bp\.blogspot\.com$/i.test(value.host) ||
             /\.(?:jpe?g|png|gif|webp|bmp|svg)$/i.test(value.path);
    }
    function isExternal(url){
      var value = parts(url);
      var current = String(window.location.hostname || '').toLowerCase();
      return !!value.host && (!current || value.host !== current);
    }
    function isAllowedHost(url){
      var host = parts(url).host;
      var i;
      for(i = 0; i < BR_ALLOWED_FILE_HOSTS.length; i += 1){
        if(host === BR_ALLOWED_FILE_HOSTS[i] || host.slice(-(BR_ALLOWED_FILE_HOSTS[i].length + 1)) === '.' + BR_ALLOWED_FILE_HOSTS[i]){ return true; }
      }
      return false;
    }
    function validFileDestination(url, imageNode){
      var value = safeUrl(String(url || '').replace(/[),.;]+$/, ''));
      var imageUrl = imageNode ? safeUrl(imageNode.getAttribute('src') || imageNode.src || '') : '';
      if(!value || isSmartLink(value)){ return ''; }
      if(imageUrl && value === imageUrl){ return ''; }
      if(isImageUrl(value) || !isExternal(value) || !isAllowedHost(value)){ return ''; }
      return value;
    }
    function remember(owner, trigger, destination){
      var value = safeUrl(destination);
      var saved;
      if(!owner || !trigger || !value){ return ''; }
      saved = safeUrl(owner.getAttribute('data-br-native-destination') || trigger.getAttribute('data-br-native-destination') || '');
      if(saved){ return saved; }
      owner.setAttribute('data-br-native-destination', value);
      trigger.setAttribute('data-br-native-destination', value);
      return value;
    }
    function explicitCandidate(anchor){
      var raw;
      var image;
      if(!anchor){ return ''; }
      raw = anchor.getAttribute('data-file-url') || anchor.getAttribute('data-download-url') || '';
      image = one(anchor, 'img');
      return validFileDestination(raw, image);
    }
    function findDestination(player){
      var trigger = one(player, '.br-player-button');
      var cached = safeUrl(player && player.getAttribute('data-br-native-destination') || '');
      var body = one(player, '.br-source-body');
      var links;
      var text;
      var marker;
      var i;
      var value;
      if(cached && isAllowedHost(cached)){ return cached; }
      if(!body || !trigger){ return ''; }

      links = all(body, 'a[data-file-url],a[data-download-url]');
      for(i = 0; i < links.length; i += 1){
        value = explicitCandidate(links[i]);
        if(value){ return remember(player, trigger, value); }
      }

      text = body.textContent || body.innerText || '';
      marker = text.match(/\[redirect\]\s*(https?:\/\/[^\s\[]+)\s*\[\/redirect\]/i);
      if(marker && marker[1]){
        value = validFileDestination(marker[1], null);
        if(value){ return remember(player, trigger, value); }
      }
      return '';
    }
    function withAgePass(value){
      var url;
      try{
        url = new URL(value, window.location.href);
        if(/^https?:$/i.test(url.protocol) && url.origin === window.location.origin){
          url.hash = 'br-age-pass';
          return url.href;
        }
      }catch(ignoreAgePassUrl){}
      return value;
    }
    function bindCard(card){
      var trigger = one(card, '.br-card-hit-target');
      var destination;
      if(!trigger){ return false; }
      destination = safeUrl(card.getAttribute('data-br-native-destination') || card.getAttribute('data-br-url') ||
                            trigger.getAttribute('data-br-native-destination') || trigger.getAttribute('data-br-target') ||
                            trigger.getAttribute('href') || trigger.href || '');
      if(!destination || isSmartLink(destination)){ return false; }
      destination = withAgePass(destination);
      destination = remember(card, trigger, destination);
      trigger.setAttribute('href', destination);
      trigger.setAttribute('target', '_self');
      trigger.setAttribute('rel', 'noopener');
      trigger.setAttribute('data-br-content-type', 'home');
      trigger.setAttribute('data-br-target', destination);
      card.setAttribute('data-br-native-bound', '1');
      return true;
    }
    function bindMissingTrigger(trigger){
      if(!trigger || trigger.getAttribute('data-br-missing-bound') === '1'){ return; }
      trigger.setAttribute('data-br-missing-bound', '1');
      trigger.addEventListener('click', function(event){
        if(event && event.preventDefault){ event.preventDefault(); }
        window.alert('File link is not configured for this post. Add data-file-url, data-download-url, or a [redirect] URL.');
