      bindPlayer: bindPlayer,
      triggerInfo: triggerInfo,
      findDestination: findDestination,
      isAllowedHost: isAllowedHost
    };
  })();
  /* Module C v11.0: transparent video-page sponsored step.
     The homepage remains native. A confirmed first Play opens the sponsored
     page in a new tab; a blocked popup never replaces the current page. */
  var VideoAdFlow = (function(){
    var SMART_URL = safeUrl(BR_VIDEO_SMARTLINK_URL);
    var TTL_MS = 1800000;
    var lifecycleBound = false;
    var MEMORY = {};

    function storage(){ try{ return window.sessionStorage || null; }catch(ignoreAccess){ return null; } }
    function stateKey(info){ return 'br-video-ad-seen-v110-' + String(hash32('video|' + info.identity)); }
    function seenAt(info){
      var key = stateKey(info);
      var target = storage();
      var value = parseInt(MEMORY[key] || '0', 10) || 0;
      try{ value = Math.max(value, parseInt(target && target.getItem(key) || '0', 10) || 0); }catch(ignoreRead){}
      return value;
    }
    function hasSeenAd(info){
      var value = seenAt(info);
      if(!value){ return false; }
      if((new Date().getTime() - value) <= TTL_MS){ return true; }
      clearSeen(info);
      return false;
    }
    function markSeen(info){
      var key = stateKey(info);
      var value = new Date().getTime();
      var target = storage();
      MEMORY[key] = value;
      try{ if(target){ target.setItem(key, String(value)); } }catch(ignoreWrite){}
    }
    function clearSeen(info){
      var key = stateKey(info);
      var target = storage();
      delete MEMORY[key];
      try{ if(target){ target.removeItem(key); } }catch(ignoreWrite){}
    }
    function infoFromTrigger(trigger){
      var info = NativeContentNavigation.triggerInfo(trigger);
      return info && info.type === 'video' ? info : null;
    }
    function syncInfo(info){
      var seen;
      if(!info || !info.destination){ return; }
      seen = !SMART_URL || hasSeenAd(info);
      info.trigger.setAttribute('href', info.destination);
      info.trigger.setAttribute('target', '_blank');
      info.trigger.setAttribute('rel', 'noopener noreferrer');
      if(seen){
        addClass(info.owner, 'br-ad-ready');
        all(info.owner, '.br-flow-long,.br-flow-short').forEach(function(node){ setText(node, 'Open File'); });
      }else{
        removeClass(info.owner, 'br-ad-ready');
        all(info.owner, '.br-flow-long,.br-flow-short').forEach(function(node){ setText(node, 'First tap: Ad · Then Open File'); });
      }
    }
    function handleClick(event){
      var info = infoFromTrigger(event && event.currentTarget);
      var approved;
      var popup;
      if(!info || !info.destination || !SMART_URL || hasSeenAd(info)){ return; }
      if(event && event.preventDefault){ event.preventDefault(); }
      approved = window.confirm('A sponsored page will open in a new tab. Return here and tap Play again to open the file. Continue?');
      if(!approved){ return; }
      popup = window.open(SMART_URL, '_blank');
      if(popup){
        try{ popup.opener = null; }catch(ignoreOpener){}
        markSeen(info);
        syncInfo(info);
      }else{
        window.alert('The sponsored tab was blocked. Allow popups for this tap or try again. Your current page was not changed.');
      }
    }
    var boundTriggers = typeof window.WeakSet === 'function' ? new window.WeakSet() : null;
    function isTriggerBound(trigger){
      return !!(trigger && (boundTriggers ? boundTriggers.has(trigger) : trigger.__brVideoFlowBoundV110 === true));
    }
    function markTriggerBound(trigger){
      if(boundTriggers){ boundTriggers.add(trigger); }
      else{ trigger.__brVideoFlowBoundV110 = true; }
      trigger.removeAttribute('data-br-video-flow-bound');
    }
    function bindTrigger(trigger){
      var info;
      if(!trigger || isTriggerBound(trigger)){ return; }
      info = infoFromTrigger(trigger);
      if(!info){ return; }
      markTriggerBound(trigger);
      trigger.addEventListener('click', handleClick, false);
      syncInfo(info);
    }
    function syncAll(){
      all(document, '.br-player-post').forEach(function(owner){
        var trigger = one(owner, '.br-player-button');
        var info = trigger ? infoFromTrigger(trigger) : null;
        if(!info){ return; }
        bindTrigger(trigger);
        syncInfo(info);
      });
    }
    function bindLifecycle(){
      if(lifecycleBound){ return; }
      lifecycleBound = true;
      if(window.addEventListener){ window.addEventListener('pageshow', syncAll, false); }
    }
    bindLifecycle();
    return { syncAll: syncAll, hasSeenAd: hasSeenAd, markSeen: markSeen, clearSeen: clearSeen, stateKey: stateKey };
  })();

  window.BRNativeContentNavigation = NativeContentNavigation;
  window.BRVideoAdFlow = VideoAdFlow;

  function isPreview(){ return !!(document.body && hasClass(document.body, 'preview')); }
  function init(){
    all(document, '.br-video-card').forEach(function(card){ applyMeta(card); NativeContentNavigation.bindCard(card); });
    all(document, '.br-player-post').forEach(function(player){ applyMeta(player); NativeContentNavigation.bindPlayer(player); });
    if(!isPreview()){ VideoAdFlow.syncAll(); }
  }

  var scheduled = false;
  var observerStarted = false;
  var booted = false;
  function scheduleInit(){
    if(scheduled){ return; }
    scheduled = true;
    (window.requestAnimationFrame || window.setTimeout)(function(){
      scheduled = false;
      init();
    }, 0);
  }
  function addedElementCanContainPost(node){
    if(!node || node.nodeType !== 1){ return false; }
    if(node.matches && node.matches('.br-video-card,.br-player-post,.blog-posts,.Blog')){ return true; }
    return !!(node.querySelector && node.querySelector('.br-video-card,.br-player-post'));
  }
  function watchBloggerUpdates(){
    var observer;
    var target = document.getElementById('main') || document.body;
    if(observerStarted || !window.MutationObserver || !target){ return; }
    observerStarted = true;
    observer = new MutationObserver(function(mutations){
      var relevant = false;
      var i;
      var j;
      for(i = 0; i < mutations.length && !relevant; i += 1){
        for(j = 0; j < mutations[i].addedNodes.length; j += 1){
          if(addedElementCanContainPost(mutations[i].addedNodes[j])){ relevant = true; break; }
        }
      }
      if(relevant){ scheduleInit(); }
    });
    observer.observe(target, { childList: true, subtree: true });
    window.__BR_BLOGGER_OBSERVER__ = observer;
  }
  function boot(){
    if(booted){ return; }
    booted = true;
    init();
    watchBloggerUpdates();
    if(window.addEventListener){ window.addEventListener('load', scheduleInit, { once: true }); }
  }

  if(document.readyState === 'loading'){ document.addEventListener('DOMContentLoaded', boot, false); }
  else{ boot(); }
})(window, document);
